import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int mod = sc.nextInt();

        final int MAXN = 505;
        int[][] C = new int[MAXN][MAXN];
        int[] way = new int[MAXN];
        int[] sum = new int[MAXN];
        int[][] g = new int[MAXN][MAXN];
        int[][] f = new int[MAXN][MAXN];

        // Initialize combination array C
        for (int i = 0; i <= m; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = mod_add(C[i - 1][j - 1], C[i - 1][j], mod);
            }
        }

        // Initialize way array
        way[0] = 1;
        for (int i = 1; i <= m; i++) {
            for (int j = 0; j < i; j++) {
                int temp1 = mod_mul(i + 1, C[i - 1][j], mod);
                int temp2 = mod_mul(way[j], way[i - j - 1], mod);
                way[i] = mod_add(way[i], mod_mul(temp1, temp2, mod), mod);

                int triangleJ = calc_triangle(j);
                int tempSum1 = mod_mul(triangleJ, way[j], mod);
                int tempSum2 = mod_mul(way[j], sum[i - j - 1], mod);
                sum[i] = mod_add(sum[i], mod_mul(tempSum1, tempSum2, mod), mod);

                int temp3 = mod_mul(mod_mul(i + 1, mod_add(tempSum2, tempSum1, mod), mod), C[i - 1][j], mod);
                sum[i] = mod_add(sum[i], temp3, mod);
            }
        }

        n = n + 1;
        f[0][0] = 1;
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                for (int k = 0; j + k <= m && i + k + 1 <= n; k++) {
                    int val_f = mod_mul(f[i][j], way[k], mod);
                    f[i + k + 1][j + k] = mod_add(f[i + k + 1][j + k], val_f, mod);
                    int val_g = mod_add(mod_mul(val_f, sum[k], mod), mod_mul(g[i][j], way[k], mod), mod);
                    g[i + k + 1][j + k] = mod_add(g[i + k + 1][j + k], val_g, mod);
                }
            }
        }

        System.out.println(g[n][m]);
        sc.close();
    }

    private static int mod_add(int a, int b, int mod) {
        int res = a + b;
        if (res >= mod) res -= mod;
        return res;
    }

    private static int mod_mul(int a, int b, int mod) {
        return (int)((long)a * b % mod);
    }

    private static int calc_triangle(int i) {
        return i * (i + 1) / 2;
    }
}
